           [('AR', W(41, 44, 9), 40), '**tas-hîl** : la seconde hamza est adoucie, entre hamza et alif', 'point au-dessus'],
           [('AR', W(12, 11, 6), 40), '**ichmâm** (lèvres arrondies) ou rawm sur le premier noûn de « ta’mannâ »', 'point au-dessus'],
