    ecoute=['Écoutez ' + W(18, 1, 11) + ' ' + W(18, 2, 1) + ' : la voix s’arrête un court instant sur l’alif, sans respiration, puis reprend.', 'Écoutez ' + W(11, 41, 6) + ' : « majrêhâ ».'],
    ret=['**Sakta** : petite pause sans respirer ; quatre sakta obligatoires pour Ḥafṣ (عِوَجَاۜ, مَّرْقَدِنَاۜ, مَنْۜ رَاقٖ, بَلْۜ رَانَ).', 'Mots spéciaux : imâla (مَجْرٜىٰهَا), tas-hîl (ءَا۬عْجَمِيّٞ), ichmâm (تَأْمَ۬نَّا), sîn (يَبْصُۜطُ, بَصْۜطَةٗ).', 'Toujours suivre les signes du Mouss-haf.'],
    lis=[W(18, 1, 11) + ' ' + W(18, 2, 1), W(36, 52, 6) + ' ' + W(36, 52, 7), W(75, 27, 2) + ' ' + W(75, 27, 3), W(83, 14, 2) + ' ' + W(83, 14, 3), [W(11, 41, 6), W(41, 44, 9), W(12, 11, 6), W(2, 245, 14), W(30, 54, 5)]],
    lis_corr=['Lignes 1 à 4 : sakta sur la fin du premier mot, sans respirer. Ligne 5 : majrêhâ • a‘jamiyyoun avec la seconde hamza adoucie • ta’mannâ avec ichmâm • wa yabsouṭou (sîn) • ḍa‘fin ou ḍou‘fin.'],
